var aiUi=require("$:/plugins/huwiki/ai/i18n.js");
var bridge=require("$:/plugins/huwiki/ai/forgeshare.js");
/*\
title: $:/plugins/huwiki/ai/image-replies.js
type: application/javascript
module-type: library

Image replies: bounded transient previews, approved ForgeShare local media, legacy Drive references.
\*/
(function(){
"use strict";
var MAX_BASE64=16*1024*1024;
var mediaIdPattern=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
function tr(da,en){return aiUi.choose(da,en);}
var avCache=new Map(),avLoads=new Map();
function cacheImage(fileId,image){avCache.set(fileId,dataUrl(image));while(avCache.size>10)avCache.delete(avCache.keys().next().value);}
function loadSavedImage(reference){
  var id=reference.mediaId||reference.id;
  if(!mediaIdPattern.test(id||""))return Promise.reject(Error(tr("Billedreferencen er ugyldig.","Invalid local image reference.")));
  if(avCache.has(id))return Promise.resolve(avCache.get(id));
  if(avLoads.has(id))return avLoads.get(id);
  var pending=bridge.call("media-get",{id:id}).then(function(reply){
    if(!reply || reply.ok!==true || reply.id!==id || !reply.mimeType || !reply.data)
      throw Error(tr("Det lokale billede kunne ikke hentes.","Could not load the local image."));
    var image=validateImage({mimeType:reply.mimeType,data:reply.data});
    cacheImage(id,image);return avCache.get(id);
  });
  avLoads.set(id,pending);
  return pending.then(function(url){avLoads.delete(id);return url;},function(e){avLoads.delete(id);throw e;});
}
function safeSvg(value){
  var s=String(value||'').trim();
  if(s.length>200000||!/^<svg\b[^>]*>[\s\S]*<\/svg\s*>$/i.test(s))return '';
  // Deliberately accept inert vector graphics only. No external loads or active XML.
  if(/<!|<\?|\bon[a-z]+\s*=|\bstyle\s*=|\b(?:href|src)\s*=|\burl\s*\(|&#|&(?!(?:amp|lt|gt|quot|apos);)/i.test(s))return '';
  var allowed=/^(?:svg|g|path|rect|circle|ellipse|line|polyline|polygon|title|desc|defs|linearGradient|radialGradient|stop|clipPath|mask|text|tspan)$/i;
  var tags=s.match(/<[^>]*>/g)||[],depth=[],valid=true;
  tags.forEach(function(tag){var m=tag.match(/^<(\/)?([A-Za-z][A-Za-z0-9]*)(\s[^<>]*|\s*)>$/);if(!m||!allowed.test(m[2])){valid=false;return;}
    if(m[1]){if(depth.pop()!==m[2])valid=false;}else if(!/\/\s*>$/.test(tag))depth.push(m[2]);
  });
  return valid&&!depth.length?s:'';
}
function validateImage(image){
  if(!image||typeof image!=='object')throw Error(aiUi.text('Billedsvaret mangler.'));
  var mime=String(image.mimeType||'').toLowerCase(),data=String(image.data||'');
  if(mime==='image/svg+xml'){
    var svg=safeSvg(data);if(!svg)throw Error(aiUi.text('SVG indeholder ikke understøttet eller aktivt indhold. Koden kan stadig gemmes som tekst.'));
    return {mimeType:mime,data:svg};
  }
  if(['image/png','image/jpeg','image/webp'].indexOf(mime)<0||!data||data.length>MAX_BASE64||data.length%4||!/^[A-Za-z0-9+/]+={0,2}$/.test(data))throw Error(aiUi.text('Billedsvaret har et ugyldigt format eller er for stort.'));
  if((mime==='image/png'&&!/^iVBORw0KGgo/.test(data))||(mime==='image/jpeg'&&!/^\/9j\//.test(data))||(mime==='image/webp'&&!/^UklGR/.test(data)))throw Error(aiUi.text('Billeddata passer ikke til formatet.'));
  return {mimeType:mime,data:data};
}
function svgImages(text){var matches=String(text||'').match(/<svg\b[\s\S]*?<\/svg\s*>/gi)||[];return matches.slice(0,2).map(function(s){return safeSvg(s);}).filter(Boolean).map(function(s){return {mimeType:'image/svg+xml',data:s};});}
function dataUrl(image){var im=validateImage(image);return im.mimeType==='image/svg+xml'?'data:'+im.mimeType+';charset=utf-8,'+encodeURIComponent(im.data):'data:'+im.mimeType+';base64,'+im.data;}
function extension(mime){return {'image/svg+xml':'svg','image/png':'png','image/jpeg':'jpg','image/webp':'webp'}[mime]||'';}
function references(message){
  try{
    var a=JSON.parse(message.imageRefs||"[]");
    return Array.isArray(a)?a.map(function(r,i){return r&&Object.assign({index:i},r);}).filter(function(r){
      return r && typeof r.title==="string" && !!extension(r.mimeType) &&
        (mediaIdPattern.test(r.mediaId||"") || /^[\w-]{10,160}$/.test(r.fileId||""));
    }).slice(0,2):[];
  }catch(e){return [];}
}
function transient(message,session){return (session&&session[message.title]||svgImages(message.text)).map(validateImage);}
function referenceFields(title,file,tags,chatTitle,messageTitle){
  if(!mediaIdPattern.test(file.id||"")||!extension(file.mimeType))throw Error(tr("Den lokale billedreference er ugyldig.","Invalid local image reference."));
  return {title:title,caption:title,type:"text/vnd.tiddlywiki",
    text:"<$huwiki-ai-image source=<<currentTiddler>>/>",
    tags:tags,"ai-media-id":file.id,"ai-media-mime":file.mimeType,"ai-media-storage":"forgeshare-local",
    "ai-source-chat":chatTitle,"ai-source-message":messageTitle,"ai-created-by":"HUWiki AI",
    created:new Date(),modified:new Date()};
}
function drawImages(w,parent,message,el,btn){
  var refs=references(message),images=transient(message,w.outputImages);
  if(!refs.length&&!images.length&&message.outputImageCount)
    el(parent,"p","huw-ai-warning",tr("Billedforslaget var midlertidigt og blev ikke gemt før genindlæsning. Samtaleteksten er bevaret.",
      "The generated image was temporary and was not saved before reload. Conversation text is preserved."));
  refs.forEach(function(ref){
    var card=el(parent,"div","huw-ai-output-image");
    if(ref.mediaId){
      var img=el(card,"img");img.alt=ref.title;
      var status=el(card,"p","huwiki-ai-help",tr("Henter lokalt billede…","Loading local image…"));
      function load(){loadSavedImage(ref).then(function(url){img.src=url;status.textContent=tr("Gemt lokalt.","Saved locally.");},function(e){status.textContent=e.message||String(e);});}
      load();
      btn(card,tr("Hent igen","Reload image"),load,"huw-ai-secondary");
    }else if(ref.fileId){
      el(card,"p","huw-ai-warning",tr(
        "Ældre Google Drive-reference. ForgeShare henter ikke længere billeder via Apps Script.",
        "Legacy Google Drive reference. ForgeShare no longer loads images through Apps Script."));
    }
    btn(card,tr("Åbn billedtiddler","Open image tiddler"),function(){w.dispatchEvent({type:"tm-navigate",navigateTo:ref.title});},"huw-ai-secondary");
  });
  images.forEach(function(image,index){
    if(refs.some(function(r){return r.index===index;}))return;
    var card=el(parent,"div","huw-ai-output-image"),img=el(card,"img");img.src=dataUrl(image);img.alt=tr("Billedforslag fra AI","Image proposal from AI");
    btn(card,tr("Gem billedet lokalt…","Save image locally…"),function(){w.openImageDialog(message,image,index);},"huw-ai-secondary");
    el(card,"p","huwiki-ai-help",tr("Midlertidigt billede. Gem lokalt for at beholde det efter genindlæsning.",
      "Temporary image. Save locally to keep it after reload."));
  });
}
function drawDialog(w,root,el,btn,field){
  var d=w.tiddlerDialog,card=el(root,"section","huwiki-ai-card huw-ai-tiddler-dialog"),image=validateImage(d.image);
  el(card,"h3",null,tr("Gem billede lokalt","Save image locally"));
  el(card,"p","huwiki-ai-help",tr(
    "Filen gemmes på Mac-computeren i ForgeShares lokale mediebibliotek for denne wiki. Tiddleren gemmer kun en reference. Et almindeligt HTML-backup indeholder ikke billedfilen.",
    "The file is stored on the Mac in ForgeShare's per-wiki media library. The tiddler stores only a reference. A normal HTML backup does not contain the image file."));
  var preview=el(card,"img","huw-ai-image-save-preview");preview.src=dataUrl(image);preview.alt=tr("Billedet der gemmes","Image to save");
  field(card,tr("Titel","Title"),d.title,function(v){d.title=v;});
  field(card,tr("Tags (adskilt med komma)","Tags (separated by commas)"),d.tags,function(v){d.tags=v;});
  var unsupported=image.mimeType==="image/svg+xml";
  if(unsupported)el(card,"p","huw-ai-warning",tr(
    "SVG kan foreløbig gemmes som tekst/kode, ikke i det lokale PNG/JPEG/WebP-bibliotek.",
    "SVG may currently be saved as text/code, not in the local PNG/JPEG/WebP library."));
  if(d.error)el(card,"p","huw-ai-warning",d.error);
  btn(card,d.saving?tr("Gemmer…","Saving…"):tr("Gem lokalt og opret tiddler","Save locally and create tiddler"),function(){
    if(d.saving||unsupported)return;
    d.saving=true;d.error="";w.draw();
    var proposed=String(d.title||tr("AI-billede","AI image")).trim();
    var tags=String(d.tags||"").split(",").map(function(t){return t.trim();}).filter(Boolean);
    Promise.resolve().then(function(){
      if(!proposed || proposed.indexOf("$:/")===0 || /[\x00-\x1f]/.test(proposed))throw Error(tr("Vælg en almindelig tiddlertitel.","Choose a regular tiddler title."));
      return bridge.call("media-save",{name:proposed.replace(/[\\/]/g,"-").slice(0,90)+"."+extension(image.mimeType),
        mimeType:image.mimeType,data:image.data});
    }).then(function(file){
      var current=$tw.wiki.getTiddler(d.message.title);
      if(!current)throw Error(tr("Samtalebeskeden findes ikke længere. Billedfilen er gemt lokalt.","The chat message no longer exists. The image was saved locally."));
      var title=proposed,n=2;
      while($tw.wiki.getTiddler(title))title=proposed+" ("+(n++)+")";
      cacheImage(file.id,image);
      $tw.wiki.addTiddler(new $tw.Tiddler(referenceFields(title,file,tags,d.chatTitle,d.message.title)));
      var refs=references({imageRefs:current.fields["ai-images"]}).filter(function(r){return r.index!==d.imageIndex;});
      refs.push({title:title,mediaId:file.id,mimeType:file.mimeType,index:d.imageIndex});
      $tw.wiki.addTiddler(new $tw.Tiddler(current,{"ai-images":JSON.stringify(refs),modified:new Date()}));
      w.tiddlerDialog=null;w.message(tr("Billedet er gemt lokalt, og en billedtiddler er oprettet.","The image was saved locally and an image tiddler was created."),false);
      w.dispatchEvent({type:"tm-navigate",navigateTo:title});
    }).catch(function(e){d.saving=false;d.error=e.message||String(e);w.draw();});
  },"huw-ai-primary").disabled=!!d.saving||unsupported;
  btn(card,tr("Gem som tekst / kode i stedet","Save as text / code instead"),function(){w.tiddlerDialog=null;w.openTiddlerDialog(d.message,true);},"huw-ai-secondary").disabled=!!d.saving;
  btn(card,tr("Annullér","Cancel"),function(){w.tiddlerDialog=null;w.draw();},"huw-ai-secondary").disabled=!!d.saving;
}

exports.safeSvg=safeSvg;exports.validateImage=validateImage;exports.svgImages=svgImages;exports.dataUrl=dataUrl;
exports.references=references;exports.transient=transient;exports.referenceFields=referenceFields;
exports.drawImages=drawImages;exports.drawDialog=drawDialog;
exports.loadSavedImage=loadSavedImage;
})();
